package com.rpb.reservation.workforce.scheduling.restswap;
import static com.rpb.reservation.workforce.scheduling.restswap.RestSwapDtos.*;
import com.rpb.reservation.workforce.application.*;import com.rpb.reservation.workforce.domain.WorkforceException;import com.rpb.reservation.workforce.scheduling.*;import com.rpb.reservation.workforce.scheduling.bulk.*;import com.rpb.reservation.workforce.calendar.CalendarRepository;import com.rpb.reservation.walkin.api.CurrentActor;
import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
@Service @Transactional(readOnly=true)
public class RestSwapPlanService {
 private final WorkforceAccess access;private final SchedulingRepository schedules;private final BulkScheduleRepository bulk;private final RestSwapRepository rests;private final CalendarRepository calendar;private final WorkforceJson json;private final Clock clock;
 public RestSwapPlanService(WorkforceAccess access,SchedulingRepository schedules,BulkScheduleRepository bulk,RestSwapRepository rests,CalendarRepository calendar,WorkforceJson json,Clock clock){this.access=access;this.schedules=schedules;this.bulk=bulk;this.rests=rests;this.calendar=calendar;this.json=json;this.clock=clock;}
 public static Request normalize(Request r){if(r==null||r.employeeIds()==null||r.employeeIds().isEmpty()||r.employeeIds().size()>500||r.employeeIds().stream().anyMatch(Objects::isNull)||r.restDate()==null||r.makeupDate()==null||r.restDate().equals(r.makeupDate())||Math.abs(ChronoUnit.DAYS.between(r.restDate(),r.makeupDate()))>30||r.shiftId()==null)throw WorkforceException.invalid();return new Request(r.employeeIds().stream().distinct().sorted().toList(),r.restDate(),r.makeupDate(),r.shiftId());}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
 public Preview preview(CurrentActor actor,UUID store,Request input){access.enter(actor,store);access.manage(actor,store);var r=normalize(input);String timezone=schedules.timezone(actor.tenantId(),store);var zone=ZoneId.of(timezone);var today=LocalDate.now(clock.withZone(zone));var from=r.restDate().isBefore(r.makeupDate())?r.restDate():r.makeupDate();var to=r.restDate().isAfter(r.makeupDate())?r.restDate():r.makeupDate();if(from.isBefore(today)||to.isAfter(today.plusDays(90)))throw WorkforceException.invalid();
 var dates=calendar.list(actor.tenantId(),store,from,to);if(dates.stream().noneMatch(e->e.enabled()&&e.date().equals(r.restDate())))throw WorkforceException.invalid();if(dates.stream().anyMatch(e->e.enabled()&&e.date().equals(r.makeupDate())&&e.kind().equals("store_rest")))throw WorkforceException.invalid();var shift=schedules.shift(actor.tenantId(),store,r.shiftId()).orElseThrow(WorkforceException::missing);if(!shift.enabled())throw WorkforceException.invalid();
 var interval=ShiftTiming.resolve(r.makeupDate(),shift,zone);Instant start=interval.start(),end=interval.end();if(!end.isAfter(start)||Duration.between(start,end).getSeconds()>86400)throw WorkforceException.invalid();var restStart=r.restDate().atStartOfDay(zone).toInstant();var restEnd=r.restDate().plusDays(1).atStartOfDay(zone).toInstant();if(start.isBefore(restEnd)&&end.isAfter(restStart))throw WorkforceException.invalid();
 var states=bulk.states(actor.tenantId(),r.employeeIds());var assignments=bulk.assignments(actor.tenantId(),store,r.employeeIds());if(states.size()!=r.employeeIds().size()||states.stream().anyMatch(e->assignments.stream().noneMatch(a->a.employeeId().equals(e.id()))))throw WorkforceException.missing();var occupied=bulk.occupied(actor.tenantId(),r.employeeIds(),from,to,from.atStartOfDay(zone).toInstant(),to.plusDays(3).atStartOfDay(zone).toInstant());var ids=occupied.stream().filter(s->s.storeId().equals(store)&&s.date().equals(r.restDate())).map(BulkScheduleRepository.Occupied::id).toList();var sources=ids.isEmpty()?List.<SchedulingRepository.Inspection>of():schedules.inspect(actor.tenantId(),ids);var guards=rests.guards(actor.tenantId(),r.employeeIds(),r.restDate(),r.makeupDate(),zone);var previous=rests.existing(actor.tenantId(),r.employeeIds(),r.restDate(),r.makeupDate());var items=new ArrayList<Item>();int ready=0,cancellations=0;
 for(var e:states){String reason="";var employeeRows=occupied.stream().filter(s->s.employeeId().equals(e.id())).toList();var cancel=employeeRows.stream().filter(s->s.storeId().equals(store)&&s.date().equals(r.restDate())).map(BulkScheduleRepository.Occupied::id).sorted().toList();
  if(previous.stream().anyMatch(p->p.get("employee_id").equals(e.id())))reason="ALREADY_SWAPPED";
  else if(!e.status().equals("active")||List.of(r.restDate(),r.makeupDate()).stream().anyMatch(d->d.isBefore(e.hireDate())||e.leaveDate()!=null&&d.isAfter(e.leaveDate())||assignments.stream().noneMatch(a->a.employeeId().equals(e.id())&&!d.isBefore(a.started())&&(a.ended()==null||d.isBefore(a.ended())))))reason="NOT_ASSIGNED";
  else if(guards.stream().anyMatch(g->g.employeeId().equals(e.id()))||sources.stream().anyMatch(s->s.schedule().employeeId().equals(e.id())&&s.used()))reason="IN_USE";
  else if(employeeRows.stream().anyMatch(s->s.storeId().equals(store)&&s.date().equals(r.makeupDate())))reason="EXISTING_MAKEUP";
  else if(employeeRows.stream().anyMatch(s->!cancel.contains(s.id())&&((s.start().isBefore(end)&&s.end().isAfter(start))||(s.start().isBefore(restEnd)&&s.end().isAfter(restStart)))))reason="TIME_OVERLAP";
  if(reason.isEmpty()){ready++;cancellations+=cancel.size();}items.add(new Item(e.id(),e.employeeNo(),e.name(),reason.isEmpty()?"ready":"conflict",reason,cancel));
 }
 return new Preview(BulkSchedulePlanService.hash(json.write(List.of("rest-swap",r,timezone,shift,states,assignments,occupied,sources,guards,previous,dates))),ready,items.size()-ready,cancellations,List.copyOf(items),timezone);
 }
}

